import {themes,templates,albumTemplates,artNames,sounds,collections,seedCards,seedAlbums,today,uid,newCard,newAlbum} from './data.js?v=20261118-album-design';
import {SoundPlayer} from './audio.js';
import {cardErrors,cardFieldLabels} from './card-validation.js?v=20261118-sound-any';
