const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const KEY='journey-create-demo-v1';
const clone=o=>structuredClone(o), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=()=>{try{return JSON.parse(localStorage.getItem(KEY))}catch{return null}};
const db=read()||{cards:clone(seedCards),albums:clone(seedAlbums),drafts:[],giftDrafts:[],wishlist:[],snapshots:{}};
db.albumDrafts ||= [];
db.purchasedAlbumIds ||= [];
// Seed a few demo purchases once, while preserving existing purchases and creations.
if(!db.demoPurchasedAlbumsV1){
 db.purchasedAlbumIds=[...new Set([...db.purchasedAlbumIds,'col-0','col-2','col-5','col-8'])];
 db.demoPurchasedAlbumsV1=true;
 try{localStorage.setItem(KEY,JSON.stringify(db))}catch{}
}

function isPurchasedAlbum(c){return !c.own&&db.purchasedAlbumIds.includes(c.id)}
function completeAlbumPurchase(){if(ui.orderAlbumId&&collections.some(c=>c.id===ui.orderAlbumId)&&!db.purchasedAlbumIds.includes(ui.orderAlbumId)){db.purchasedAlbumIds.push(ui.orderAlbumId);persist()}}

db.customThemes ||= [];
db.customSubthemes ||= {};
function refreshDemoAlbumCover(a){if(!a||a.type!=='album')return;const i=['album-seed-0','album-seed-1'].indexOf(a.id);if(i>=0&&(!a.photo||a.photo==='art:'+i))a.photo='album-art:'+i}
db.albums.forEach(refreshDemoAlbumCover);db.albumDrafts.forEach(refreshDemoAlbumCover);refreshDemoAlbumCover(db.currentAlbum);
(db.currentGift?.items||[]).forEach(refreshDemoAlbumCover);(db.currentGift?.collectionItems||[]).forEach(refreshDemoAlbumCover);
let giftCinema=null;
let card=db.currentCard||newCard(),album=db.currentAlbum||newAlbum(),gift=db.currentGift||{recipient:'',occasion:'Birthday',kind:'',items:[],speaker:0,color:'Paper white',engraving:'',collection:null};
let ui={theme:0,template:0,photoFor:'card',photoReturn:'editor',soundFor:'card',soundReturn:'editor',libraryType:'card',libraryStatus:'completed',artistCategory:'All',soundCategory:'All',collectionCategory:'All',search:'',soundSearch:'',pickSound:null,soundExpanded:false,collection:0,speaker:0,selected:[],selectionType:'card',detail:null,detailOrigin:'library',shareMode:'share',shareReturn:'detail',recordStage:'permission',recordPaused:false,recordSeconds:0,recordBlob:null,flipped:false,physical:false,writingStep:0,hardwareConnected:false,hardwareCard:false,order:'',orderReturn:'detail',error:'',mixSaved:false};
try{ui={...ui,...JSON.parse(sessionStorage.getItem(KEY+'-view')||'{}')}}catch{}
function rememberUI(){try{sessionStorage.setItem(KEY+'-view',JSON.stringify(ui))}catch{}}
let trail=[],route=(location.hash.slice(2).split('?')[0]||'home'),toastTimer,recordTimer,recorder,recordStream,chunks=[],recStarted=0,activeGeneration=null;
const player=new SoundPlayer(updatePlayer);
const icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
const icons=()=>window.lucide?.createIcons({attrs:{'aria-hidden':'true'}});
const attr=o=>Object.entries(o||{}).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ');
const ib=(i,label,action,data={})=>`<button type="button" class="icon-button" aria-label="${esc(label)}" data-action="${action}" ${attr(data)}>${icon(i)}</button>`;
const primary=(label,action,disabled=false)=>`<button type="button" class="primary" data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
const textButton=(label,action)=>`<button type="button" class="text-button" data-action="${action}">${label}</button>`;
const secondary=(label,action)=>`<button type="button" class="secondary-button" data-action="${action}">${label}</button>`;
const row=(title,sub,action,data={},disabled=false)=>`<button type="button" class="option-row" data-action="${action}" ${attr(data)} ${disabled?'disabled':''}><span><strong>${esc(title)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</span>${icon('chevron-right')}</button>`;
const field=(label,name,value,type='text',required=false)=>`<label class="field"><span>${esc(label)}${required?' <span aria-hidden="true">*</span>':''}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} autocomplete="off"></label>`;
const textarea=(label,name,value,required=false)=>`<label class="field"><span>${label}${required?' *':''}</span><textarea name="${name}" rows="3" ${required?'required':''}>${esc(value)}</textarea></label>`;
const heading=(title,subtitle='')=>`<header class="page-heading"><h1 class="${title.length>40?'long-title':''}" tabindex="-1">${esc(title)}</h1>${subtitle?`<p class="subtitle">${esc(subtitle)}</p>`:''}</header>`;
const top=(back=true,action='')=>`<div class="topbar">${back?ib('arrow-left','Back','back'):'<span></span>'}${action}</div>`;
const nav=current=>`<nav class="bottom-nav" aria-label="Main navigation">${[['home','house','Home'],['practice','person-standing','Practice'],['create','square-pen','Create'],['share-hub','share-2','Share']].map(([id,i,t])=>`<button data-go="${id}" ${current===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;
const shell=(body,{title='',subtitle='',back=true,topAction='',footer='',navigation='',className=''}={})=>`<div class="view"><div class="content ${className}">${top(back,topAction)}${title?heading(title,subtitle):''}${ui.error?`<p class="inline-error" role="alert">${esc(ui.error)}</p>`:''}${body}</div>${footer?`<div class="sticky-actions">${footer}</div>`:''}${navigation&&['home','create','practice','share-hub'].includes(route)?nav(navigation):''}</div>`;
const art=(object,extra='')=>{let p=object?.photo||`art:${object?.art||0}`;return p.startsWith('album-art:')?`<div class="art album-art album-art-${parseInt(p.split(':')[1])===1?1:0} ${extra}" role="img" aria-label="${parseInt(p.split(':')[1])===1?'Sunlit sea and quiet coastline':'Apricot blossoms above distant mountains'}"></div>`:p.startsWith('dunhuang:')?`<div class="art dunhuang-art dunhuang-${Math.max(0,Math.min(2,parseInt(p.split(':')[1])||0))} ${extra}" role="img" aria-label="${esc(['Moon over sand dunes','A flowering branch','Bird above distant mountains'][parseInt(p.split(':')[1])||0]||'Dunhuang artwork')}"></div>`:p.startsWith('data:')||p.startsWith('blob:')?`<div class="art ${extra}"><img src="${esc(p)}" alt="${esc(object?.name||'Selected photo')}" style="object-position:${object?.cropX||50}% ${object?.cropY||50}%"></div>`:`<div class="art art-${(parseInt(p.split(':')[1])||0)%4} ${extra}" role="img" aria-label="${esc(artNames[object?.art||0]||'Paper Zen study')}"></div>`};
function albumArtwork(a){return {...a,photo:a.photo||'album-art:0'}}
function albumBackMarkup(a,n){const cards=(a.cardIds||[]).map(id=>(a.snapshots||[]).find(c=>c.id===id)||getCreation(id)).filter(Boolean);const entries=cards.length?cards.slice(0,3).map(c=>c.name):['A quiet beginning','A moment to keep','Something to return to'];return `<div class="album-back-layout album-back-layout-${n}"><span class="album-back-eyebrow">SOUND ALBUM</span><h3>${esc(a.name||'Collected moments')}</h3><p>${esc(a.description||'Small moments, gathered with care. A place to return to, whenever you need.')}</p><ol>${entries.map(name=>`<li>${esc(name)}</li>`).join('')}</ol><small>${cards.length||entries.length} sound cards</small><span class="album-back-mark" aria-hidden="true">${icon('audio-lines')}</span></div>`}
function albumObject(a,{large=false,front=false,back=false,qr=false}={}){const n=Math.max(0,Math.min(2,Number(a.template)||0));return `<div class="album-object album-format-${n} ${large?'album-object-large':''} ${front?'album-front-view':''} ${back?'album-back-view':''}" role="img" aria-label="${esc(albumTemplates[n].title+': '+(a.name||a.title||'Your album'))}"><div class="album-volume">${n===1?`<div class="album-fold" aria-hidden="true">${art(albumArtwork(a))}</div>`:''}<div class="album-front">${back?albumBackMarkup(a,n):`${art(albumArtwork(a))}<strong>${esc(a.name||a.title||'Your album')}</strong>`}</div></div>${qr?'<span class="qr-target" aria-label="QR code for this demo"></span>':''}</div>`}
const paperCard=(c,{large=false,qr=false,flipped=ui.flipped}={})=>c.type==='album'?albumObject(c,{large,qr}):`<div class="paper-card ${large?'paper-card-large':''} template-${c.template||0} ${flipped?'is-back':''}">${flipped?`<div class="card-back"><span class="card-back-title">${esc(c.name||templates[c.template||0].title)}</span><p>${esc(c.words||'A moment I want to keep.')}</p><small>${esc(c.date||today())}</small></div>`:art(c)}${flipped?'':`<div class="card-print"><span>${esc(c.name||templates[c.template||0].title)}</span></div>`}${qr?'<span class="qr-target" aria-label="QR code for this demo"></span>':''}</div>`;
const mediaPlayer=({mini=false,replay=false}={})=>`<div class="media-player ${mini?'mini-player':''}"><input aria-label="Playback progress" data-audio-progress type="range" min="0" max="${player.duration}" value="${player.current}" step="1"><div class="player-times"><span data-current>${time(player.current)}</span><span data-duration>${time(player.duration)}</span></div><div class="player-controls">${ib(replay?'rotate-ccw':'rewind',replay?'Replay':'Go back 15 seconds',replay?'replay':'rewind')}<button class="play-button" data-action="play" aria-label="${player.playing?'Pause':'Play'}">${icon(player.playing?'pause':'play')}</button>${ib('fast-forward','Go forward 15 seconds','forward')}</div></div>`;
function time(n){n=Math.max(0,Math.floor(n||0));return Math.floor(n/60).toString().padStart(2,'0')+':'+(n%60).toString().padStart(2,'0')}
function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function persist(){if((card.status==='draft'||card.editId)&&(card.name||card.words||card.photo)){db.drafts=db.drafts.filter(d=>d.id!==card.id);db.drafts.unshift(clone({...card,status:'draft'}));}if(album.status==='draft' && album.name?.trim()){db.albumDrafts=db.albumDrafts.filter(a=>a.id!==album.id);db.albumDrafts.unshift(clone(album));}try{localStorage.setItem(KEY,JSON.stringify({...db,currentCard:card,currentAlbum:album,currentGift:gift}));return true}catch{notify('Storage is full. Your current work is kept on this page.');return false}}
function saveDraft(){if(card.name||card.words||card.photo){const d={...card,status:'draft'};db.drafts=db.drafts.filter(x=>x.id!==d.id);db.drafts.unshift(d);}persist()}
function go(next,{remember=true,stop=true}={}){if(route==='gift-preview'&&next!==route){giftCinema?.destroy();giftCinema=null;}if(stop)player.pause();if(route==='recording'&&recorder&&recorder.state!=='inactive'){recorder.stop();stopRecordingTracks();}if(remember&&route!==next)trail.push(route);ui.error='';route=next;if(location.hash!=='#/'+next)location.hash='/'+next;render()}
function back(){ui.error='';if(ui.albumCreating&&route==='album'){ui.albumBack=false;ui.albumFront=false;ui.templateFor='album';ui.template=album.template||0;ui.templateReturn='album-cards';go('template',{remember:false});return;}if(ui.albumCreating&&route==='album-preview'){go('album',{remember:false});return;}if(ui.albumCreating&&route==='album-cards'){if(ui.albumCardsReturn){go(ui.albumCardsReturn,{remember:false});ui.albumCardsReturn=null;return;}persist();const target=ui.albumReturn==='gift-albums'?'gift-albums':ui.albumReturn==='library-albums'?'library':'create';ui.albumCreating=false;ui.libraryType='album';go(target,{remember:false});return;}if(route==='album-detail'&&ui.detailOrigin==='gift-album-picker'){go('gift-albums',{remember:false});return;}if(route==='album'&&ui.albumReturn){const returnTo=ui.albumReturn;ui.albumReturn=null;persist();ui.collectionPicking=returnTo==='gift-albums';ui.libraryType='album';ui.libraryStatus='completed';go(returnTo==='gift-albums'?'gift-albums':'library',{remember:false});return;}if(route==='gift-albums'){ui.collectionPicking=false;go('bazaar',{remember:false});return;}if(route==='blessing-preview'){go('editor',{remember:false});return;}motionIntent('back',true);if(route==='gift-preview'){go('gift-summary',{remember:false});return;}if(route==='memory'||route==='library'||route==='explore'||route==='gift'){go('create',{remember:false});return;}if(route==='subtheme'){go('memory',{remember:false});return;}if(route==='template'){go(ui.templateReturn||'editor',{remember:false});return;}if(route==='photo'){go(ui.photoReturn||'editor',{remember:false});return;}if(route==='artist'||route==='photos'){go('photo',{remember:false});return;}if(route==='crop'){go(ui.cropReturn||'photo',{remember:false});return;}if(route==='mixer'){go('sound',{remember:false});return;}if(route==='gift-types'){go('gift',{remember:false});return;}if(['gift-summary','gift-speaker','gift-card-choice'].includes(route)){go('gift-types',{remember:false});return;}if(route==='gift-picker'){go('gift-card-choice',{remember:false});return;}if(route==='gift-drafts'){go('gift',{remember:false});return;}if(route==='detail'&&ui.parentDetail){const p=ui.parentDetail;ui.detail=p.item;ui.detailOrigin=p.origin;ui.parentDetail=null;go(p.route,{remember:false});return;}if(route==='recording'){stopRecordingTracks();go('sound',{remember:false});return;}if(route==='sound-library'){ui.pickSound=null;ui.soundExpanded=false;go('sound',{remember:false});return;}if(route==='sound'){go(ui.soundReturn,{remember:false});return;}if(route==='share'||route==='export'){go(ui.shareReturn,{remember:false});return;}if(route==='detail'&&card.source==='album'&&ui.detail?.id===card.id){go('album-cards',{remember:false});return;}if(route==='editor'){saveDraft();go(card.source==='album'?'album-cards':card.source==='gift'?(gift.kind==='set'?'gift-summary':'gift-card-choice'):card.source==='memory'?'template':'create',{remember:false});return;}go(trail.pop()||'create',{remember:false})}
function beginCard(source,topic='',subtopic=''){card=newCard(source,topic,subtopic);ui.templateReturn=source==='memory'?'subtheme':source==='simple'?'create':'editor';ui.replaceGiftCard=null;ui.parentDetail=null;ui.template=0;ui.templateBack=false;ui.templateFor='card';if(source==='gift')card.words=`Dear ${gift.recipient}, `;ui.flipped=false;ui.photoFor='card';ui.soundFor='card';saveDraft();go(['memory','simple'].includes(source)?'template':'editor')}
function getCreation(id){return db.cards.find(c=>c.id===id)||db.albums.find(c=>c.id===id)||db.snapshots[id]||seedCards.find(c=>c.id===id)||seedAlbums.find(c=>c.id===id)}
function currentItem(){return ui.detail||getCreation(card.id)||card}
function openDetail(item,origin='library'){ui.detail=clone(item);ui.detailOrigin=origin;ui.physical=false;ui.flipped=false;const track=item.type==='album'&&item.intro&&typeof item.intro==='object'?item.intro:item;player.configure({voice:track.recording,limit:track.recordingDuration||null,voiceVolume:track.voiceVolume,soundVolume:track.soundVolume,background:!!track.sound});go(item.type==='album'?'album-detail':'detail')}
function soundState(){return ui.soundFor==='intro'?(album.introDraft||(album.introDraft={recording:null,sound:null,mixed:false,voiceVolume:75,soundVolume:30})):card}
function configureSound(){const s=soundState();player.configure({voice:s.recording,limit:s.recordingDuration||(s.recording==='demo'?30:null),background:!!s.sound,voiceVolume:s.voiceVolume??75,soundVolume:s.soundVolume??30})}
function creationGrid(items,{columns=4,multi=false,selected=[],action='open-detail',date=false,creator=false,reorder=false}={}){return `<div class="creation-grid columns-${columns}">${items.map((c,i)=>`<div class="grid-cell ${multi&&selected.includes(c.id)?'selected':''}" ${reorder?`draggable="true" data-drag-id="${esc(c.id)}"`:''}><button class="grid-creation" data-action="${action}" data-id="${esc(c.id)}" ${multi?`aria-pressed="${selected.includes(c.id)}"`:''} aria-label="${esc((multi?'Select ':'Open ')+c.name)}">${c.type==='album'?albumObject(c):art(c)}${multi?`<span class="selection-check">${selected.includes(c.id)?icon('check'):''}</span>`:''}${reorder?`<span class="order-number">${i+1}</span>`:''}<strong>${esc(c.name)}</strong>${date?`<small>${esc(c.date)}</small>`:''}${creator?`<small>${esc(c.creator||'You')}</small>`:''}</button>${reorder?`<div class="reorder-actions">${ib('ellipsis','Arrange '+c.name,'arrange-card-menu',{id:c.id})}</div>`:''}</div>`).join('')}</div>`}
const templateSampleWords=["那天没有发生什么大事。\n风吹过沙丘，月亮慢慢升起。\n我只是安静地坐了一会儿，\n却想把这一刻留很久。","想记住你说话时的笑意，\n桌边的花，还有渐凉的茶。\n原来值得珍藏的日子，\n也可以这样平常。","那一天，我终于向前走了。\n风很轻，远山还在远处。\n把这一刻留给未来的自己：\n记得出发时，心里的光。"];
function albumTemplateView(){const t=albumTemplates[ui.template],preview={...album,type:'album',template:ui.template,name:album.name||'Collected moments'};return shell(`<div class="template-carousel album-template-carousel" data-swipe="template">${ib('chevron-left','Previous album template','prev-template')}<button type="button" class="album-template-preview" data-action="flip-album-template" aria-label="${ui.albumBack?'Show front of album':'Show back of album'}" aria-describedby="album-flip-hint">${albumObject(preview,{large:true,back:!!ui.albumBack})}</button>${ib('chevron-right','Next album template','next-template')}</div><div class="template-caption"><h2>${esc(t.title)}</h2><p class="album-template-description">${esc(t.description)}</p></div><p class="template-flip-hint" id="album-flip-hint">${ui.albumBack?'Back':'Front'} · Tap to flip</p><div class="template-page-control" aria-label="Choose album template">${albumTemplates.map((x,i)=>`<button class="template-page-dot" data-action="set-template" data-index="${i}" aria-label="${esc(x.title)}" aria-pressed="${ui.template===i}"><span aria-hidden="true"></span></button>`).join('')}</div>`,{topAction:'<span class="template-nav-title">Album template</span>',footer:primary('Use album template','use-template')})}
function templateView(){if(ui.templateFor==='album')return albumTemplateView();
 const t=templates[ui.template],preview={name:card.name||t.title,words:card.words||templateSampleWords[ui.template],date:card.date||today(),photo:`dunhuang:${ui.template}`,template:ui.template};
 return shell(`<div class="template-carousel" data-swipe="template">${ib('chevron-left','Previous template','prev-template')}<button type="button" class="template-flip ${ui.templateBack?'show-back':''}" data-action="flip-template" aria-label="${ui.templateBack?'Show front of template':'Show back of template'}" aria-describedby="template-flip-hint"><span class="template-flip-inner"><span class="template-face template-face-front" aria-hidden="${!!ui.templateBack}">${paperCard(preview,{large:true,flipped:false})}</span><span class="template-face template-face-back" aria-hidden="${!ui.templateBack}">${paperCard(preview,{large:true,flipped:true})}</span></span></button>${ib('chevron-right','Next template','next-template')}</div><div class="template-caption"><h2>${t.title}</h2></div><p class="template-flip-hint" id="template-flip-hint"><span data-template-side>${ui.templateBack?'Back':'Front'}</span> · Tap to flip</p><div class="template-page-control" aria-label="Choose template">${templates.map((_,i)=>`<button type="button" class="template-page-dot" data-action="set-template" data-index="${i}" aria-label="Template ${i+1}: ${esc(templates[i].title)}" aria-pressed="${i===ui.template}"><span aria-hidden="true"></span></button>`).join('')}</div>`,{topAction:'<span class="template-nav-title">Choose a template</span>',footer:primary('Use template','use-template')});
}
function editorField(key,body){return `<div class="card-field" data-card-field="${key}">${body}<p class="card-field-error" id="card-${key}-error" hidden></p></div>`}
const editorHierarchyStyle=document.createElement('style');
editorHierarchyStyle.id='quiet-sand-editor-hierarchy';
editorHierarchyStyle.textContent="/* Editor hierarchy trial: labels / values / helper copy. */\n[data-route=\"editor\"] #card-form .field>span,\n[data-route=\"editor\"] #card-form .option-row strong{\n font-family:var(--qs-ui);font-size:1.0625rem;line-height:24px;font-weight:500;color:#363A32;\n}\n[data-route=\"editor\"] #card-form .field{gap:8px}\n[data-route=\"editor\"] #card-form .option-row small{\n display:block;margin-top:8px;font-family:var(--qs-ui);font-size:.8125rem;line-height:18px;font-weight:400;color:#68675B;\n}\n[data-route=\"editor\"] #card-form .option-row[data-selected=\"true\"] small{\n font-size:1.0625rem;line-height:26px;color:#363A32;\n}\n[data-route=\"editor\"] #card-form .field input,\n[data-route=\"editor\"] #card-form .field textarea{\n font-size:1.0625rem;line-height:26px;font-weight:400;color:#363A32;\n}\n[data-route=\"editor\"] #card-form .draft-status{\n font-size:.8125rem;line-height:18px;font-weight:400;color:#68675B;\n}\n";
editorHierarchyStyle.textContent+="\n[data-route=\"editor\"] #card-form .editor-asset-field{display:grid;gap:8px}\n[data-route=\"editor\"] #card-form .editor-field-label{font-family:var(--qs-ui);font-size:1.0625rem;line-height:24px;font-weight:500;color:#363A32}\n[data-route=\"editor\"] #card-form .editor-asset-option{min-height:56px;padding:16px;margin:0;width:100%}\n[data-route=\"editor\"] #card-form .editor-asset-value{font-family:var(--qs-ui);font-size:.8125rem;line-height:18px;font-weight:400;color:#68675B;text-align:left}\n[data-route=\"editor\"] #card-form .editor-asset-option[data-selected=\"true\"] .editor-asset-value{font-size:1.0625rem;line-height:26px;color:#363A32}\n";
editorHierarchyStyle.textContent+="\n/* Compact asset preview strips, variant A. */\n[data-route=\"editor\"] #card-form .editor-asset-option{display:flex;align-items:center;gap:12px;min-height:80px;padding:12px 4px 12px 12px;border:0;border-bottom:1px solid #D9CDBB;border-radius:0;background:rgba(251,246,237,.55);box-shadow:none}\n[data-route=\"editor\"] #card-form .editor-asset-visual{display:grid;place-items:center;flex:0 0 48px;width:48px;height:48px;overflow:hidden;border-radius:6px;background:#E7E4D5;color:#4F6557}\n[data-route=\"editor\"] #card-form .editor-asset-visual>svg{width:24px;height:24px;stroke-width:1.6}\n[data-route=\"editor\"] #card-form .editor-asset-visual .art{width:100%;height:100%;min-height:0;aspect-ratio:1;margin:0;padding:0;border:0;border-radius:0}\n[data-route=\"editor\"] #card-form .editor-asset-visual img{width:100%;height:100%;object-fit:cover}\n[data-route=\"editor\"] #card-form .editor-asset-copy{flex:1;min-width:0;display:grid;gap:4px;text-align:left}\n[data-route=\"editor\"] #card-form .editor-asset-option .editor-asset-value{font-size:1.0625rem;line-height:24px;font-weight:400;color:#363A32}\n[data-route=\"editor\"] #card-form .editor-asset-detail{font-family:var(--qs-ui);font-size:.8125rem;line-height:18px;font-weight:400;color:#68675B}\n[data-route=\"editor\"] #card-form .editor-asset-action{display:grid;place-items:center;flex:0 0 44px;min-height:44px;font-family:var(--qs-ui);font-size:.8125rem;font-weight:500;color:#4F6557}\n[data-route=\"editor\"] #card-form .editor-asset-action svg{width:20px;height:20px}\n[data-route=\"editor\"] #card-form .asset-wave{display:flex;align-items:center;justify-content:center;gap:3px;height:30px}\n[data-route=\"editor\"] #card-form .asset-wave b{display:block;width:2px;background:currentColor;border-radius:2px}\n[data-route=\"editor\"] #card-form .editor-asset-option:focus-visible{outline:2px solid #4F6557;outline-offset:3px}\n[data-route=\"editor\"] #card-form .has-error .editor-asset-option{border-bottom-color:#974E43}\n@media(hover:hover){[data-route=\"editor\"] #card-form .editor-asset-option:hover{background:#FBF6ED}}\n";
editorHierarchyStyle.textContent+="\n[data-route=\"sound\"] .sound-asset-row{gap:16px}\n[data-route=\"sound\"] .sound-asset-row[data-complete=\"true\"]{background:#E7E8DA;border-color:#C5CBB8}\n[data-route=\"sound\"] .sound-asset-copy{flex:1;min-width:0;text-align:left}\n[data-route=\"sound\"] .sound-asset-row strong{display:block;font-family:var(--qs-ui);font-size:1.0625rem;line-height:24px;font-weight:500;color:#363A32;overflow-wrap:anywhere}\n[data-route=\"sound\"] .sound-asset-row small{display:block;margin-top:6px;font-family:var(--qs-ui);font-size:.8125rem;line-height:18px;color:#68675B}\n[data-route=\"sound\"] .sound-asset-trailing{display:flex;flex-direction:column;align-items:flex-end;gap:6px;flex-shrink:0;color:#4F6557}\n[data-route=\"sound\"] .sound-complete{display:flex;align-items:center;gap:4px;font-size:.75rem;line-height:18px;font-weight:400}\n[data-route=\"sound\"] .sound-complete svg{width:14px;height:14px}\n[data-route=\"sound\"] .sound-edit{font-size:.8125rem;line-height:18px;font-weight:500}\n[data-route=\"sound\"] .sound-asset-row:focus-visible{outline:2px solid #4F6557;outline-offset:3px}\n";
editorHierarchyStyle.textContent+="\n/* Generated Dunhuang artwork and three distinct printed card compositions. */\n.art.dunhuang-art{background-image:url('assets/dunhuang-template-atlas.svg');background-size:300% 100%;background-repeat:no-repeat;background-color:#E8D4B4}\n.art.dunhuang-0{background-position:0% 50%}.art.dunhuang-1{background-position:50% 50%}.art.dunhuang-2{background-position:100% 50%}\n.paper-card:not(.is-back){container-type:inline-size;aspect-ratio:4/5;display:grid;overflow:hidden;padding:6%;gap:0;border-radius:6px}\n.paper-card:not(.is-back)>.art{width:100%;height:100%;min-height:0;aspect-ratio:auto;border:0;padding:0}\n.paper-card:not(.is-back)>.card-print{min-width:0;min-height:0;margin:0;padding:0;font-family:var(--qs-display);font-size:clamp(8px,6cqw,23px);line-height:1.3;overflow-wrap:anywhere;overflow:hidden;color:#363A32}\n.paper-card.template-0:not(.is-back){grid-template-rows:minmax(0,1fr) 18%;gap:5%;padding:5%}\n.paper-card.template-0:not(.is-back)>.card-print{justify-content:center;border-top:1px solid #D9CDBB;padding-top:4%;text-align:left}\n.paper-card.template-1:not(.is-back){grid-template-columns:57% minmax(0,1fr);grid-template-rows:1fr;gap:7%;padding:8% 6%}\n.paper-card.template-1:not(.is-back)>.art{border-radius:45% 45% 0 0}\n.paper-card.template-1:not(.is-back)>.card-print{justify-content:flex-end;padding-bottom:18%;font-size:clamp(8px,7cqw,25px)}\n.paper-card.template-2:not(.is-back){grid-template-rows:23% minmax(0,1fr);gap:5%;padding:8% 10%}\n.paper-card.template-2:not(.is-back)>.card-print{grid-row:1;text-align:center;align-items:center;justify-content:center}\n.paper-card.template-2:not(.is-back)>.art{grid-row:2;border-radius:48% 48% 3px 3px}\n.paper-card.is-back .card-print{font-family:var(--qs-display)}\n.editor-mini-preview .paper-card:not(.is-back){padding:5px;gap:4px}\n.editor-mini-preview .paper-card:not(.is-back) .card-print{font-size:8px}\n";
editorHierarchyStyle.textContent+="\n/* Front/back template preview and matching content typography. */\n.template-flip{display:block;position:relative;width:100%;max-width:282px;aspect-ratio:4/5;margin:auto;padding:0;border:0;border-radius:6px;background:transparent;perspective:1200px;text-align:left;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}\n.template-flip:focus-visible{outline:2px solid #4F6557;outline-offset:5px}\n.template-flip-inner{display:block;position:absolute;inset:0;transform-style:preserve-3d;transition:transform .55s cubic-bezier(.2,.65,.3,1)}\n.template-flip.show-back .template-flip-inner{transform:rotateY(180deg)}\n.template-face{display:block;position:absolute;inset:0;backface-visibility:hidden;-webkit-backface-visibility:hidden}\n.template-face-back{transform:rotateY(180deg)}\n.template-face .paper-card{width:100%;height:100%;max-width:none}\n.template-flip-hint{text-align:center;font-family:var(--qs-ui);font-size:13px;line-height:18px;color:#68675B;margin:12px 0}\n.paper-card.is-back{container-type:inline-size;aspect-ratio:4/5;padding:8%;display:block;overflow:hidden;background:#FBF6ED}\n.paper-card.is-back .card-back{display:flex;flex-direction:column;aspect-ratio:auto;min-height:0;height:100%;padding:0;background:transparent;gap:7%;justify-content:flex-start;color:#363A32}\n.card-back-title{font-family:var(--qs-display);font-size:clamp(9px,7cqw,24px);line-height:1.25;overflow-wrap:anywhere}\n.paper-card.is-back .card-back p{font-family:var(--qs-ui);font-size:clamp(6px,4.8cqw,16px);line-height:1.65;margin:0;white-space:pre-wrap;overflow-wrap:anywhere;overflow:auto;min-height:0}\n.paper-card.is-back .card-back small{font-family:var(--qs-ui);font-size:clamp(5px,3.8cqw,12px);line-height:1.5;color:#68675B;margin-top:auto}\n.paper-card.template-0.is-back .card-back-title{border-bottom:1px solid #D9CDBB;padding-bottom:8%}\n.paper-card.template-1.is-back{padding:10% 9% 9% 13%}\n.paper-card.template-1.is-back .card-back{border-left:1px solid #AD7967;padding-left:9%}\n.paper-card.template-1.is-back .card-back-title{font-size:clamp(9px,6cqw,21px)}\n.paper-card.template-1.is-back .card-back p{font-family:var(--qs-display);font-size:clamp(6px,5.6cqw,19px);line-height:1.6}\n.paper-card.template-2.is-back{padding:13% 10% 10%}\n.paper-card.template-2.is-back .card-back{align-items:center;justify-content:center;text-align:center}\n.paper-card.template-2.is-back .card-back-title{font-size:clamp(9px,6.5cqw,22px)}\n.paper-card.template-2.is-back .card-back small{margin-top:4%;border-top:1px solid #D9CDBB;padding-top:8%;width:50%}\n@media(prefers-reduced-motion:reduce){.template-flip-inner{transition:none}}\n";
editorHierarchyStyle.textContent+="\n/* Keep the template chooser within the available phone viewport. */\n[data-route=\"template\"]>.view>.content{display:grid;grid-template-rows:44px auto minmax(0,1fr) auto auto auto;gap:6px;min-height:0;padding:6px 20px 10px;overflow-y:auto}\n[data-route=\"template\"] .topbar{height:44px;margin:0 -8px}\n[data-route=\"template\"] .page-heading{margin:0}\n[data-route=\"template\"] .page-heading h1{font-size:var(--qs-page);line-height:36px}\n[data-route=\"template\"] .template-carousel{container-type:size;min-height:0;grid-template-columns:44px minmax(0,1fr) 44px;gap:4px;align-items:center;justify-items:center;margin:0}\n[data-route=\"template\"] .template-carousel>.icon-button{width:44px;min-width:44px;height:44px;padding:10px}\n[data-route=\"template\"] .template-flip{width:min(100%,282px,80cqh);max-height:100%;margin:0}\n[data-route=\"template\"] .template-flip-hint{margin:0;font-size:12px;line-height:18px}\n[data-route=\"template\"] .carousel-dots{margin:0;min-height:24px;gap:4px}\n[data-route=\"template\"] .carousel-dots .dot{position:relative;display:grid;place-items:center;width:24px;height:24px;min-width:24px;border:0;background:transparent}\n[data-route=\"template\"] .carousel-dots .dot:before{content:'';width:6px;height:6px;border:1px solid #4F6557;border-radius:50%;background:transparent}\n[data-route=\"template\"] .carousel-dots .dot.selected:before{background:#4F6557}\n[data-route=\"template\"] .template-caption{margin:0}\n[data-route=\"template\"] .template-caption h2{font-size:20px;line-height:26px;margin:0}\n[data-route=\"template\"] .template-caption p{font-size:13px;line-height:18px;margin:3px 0 0}\n[data-route=\"template\"] .sticky-actions{flex-shrink:0;padding:10px 24px;gap:0}\n@media(max-height:440px){[data-route=\"template\"]>.view>.content{grid-template-rows:44px auto minmax(120px,1fr) auto auto auto}}\n";
editorHierarchyStyle.textContent+="\n/* Airy iOS-style template chooser: one navigation title, one preview, one action. */\n[data-route=\"template\"]>.view>.content{grid-template-rows:44px minmax(0,1fr) auto auto 32px;gap:12px;padding:8px 24px 18px;min-height:0}\n[data-route=\"template\"] .topbar{display:grid;grid-template-columns:44px minmax(0,1fr) 44px;align-items:center;margin:0 -12px;height:44px}\n[data-route=\"template\"] .template-nav-title{font-family:var(--qs-ui);font-size:17px;line-height:22px;font-weight:500;text-align:center;white-space:nowrap}\n[data-route=\"template\"] .template-carousel{grid-template-columns:44px minmax(0,1fr) 44px;gap:0;margin:0;min-height:0}\n[data-route=\"template\"] .template-flip{width:min(100%,220px,72cqh);max-height:90%;margin:0}\n[data-route=\"template\"] .template-caption{margin:0;text-align:center}\n[data-route=\"template\"] .template-caption h2{font-family:var(--qs-display);font-size:20px;line-height:26px;margin:0}\n[data-route=\"template\"] .template-flip-hint{font-size:12px;line-height:18px;margin:-6px 0 0;color:#68675B}\n[data-route=\"template\"] .template-page-control{display:flex;align-items:center;justify-content:center;gap:0;height:32px}\n[data-route=\"template\"] .template-page-dot{display:grid;place-items:center;width:32px;height:32px;min-width:32px;padding:0;margin:0;border:0;border-radius:0;background:transparent;box-shadow:none}\n[data-route=\"template\"] .template-page-dot::before,[data-route=\"template\"] .template-page-dot::after{content:none!important;display:none!important}\n[data-route=\"template\"] .template-page-dot>span{display:block;width:6px;height:6px;border:0;border-radius:50%;background:#C9CCBE}\n[data-route=\"template\"] .template-page-dot[aria-pressed=\"true\"]>span{background:#4F6557}\n[data-route=\"template\"] .template-page-dot:focus-visible{outline:2px solid #4F6557;outline-offset:-2px}\n[data-route=\"template\"] .sticky-actions{padding:12px 24px 16px;border-top:0;gap:0}\n[data-route=\"template\"] .sticky-actions>.primary{min-height:50px;font-size:17px;line-height:24px}\n@media(max-height:480px){[data-route=\"template\"]>.view>.content{gap:8px;padding-top:4px;padding-bottom:8px;grid-template-rows:44px minmax(90px,1fr) auto auto 28px}[data-route=\"template\"] .template-page-control{height:28px}[data-route=\"template\"] .sticky-actions{padding-top:8px;padding-bottom:8px}}\n";
editorHierarchyStyle.textContent+="\n[data-route=\"gift-speaker\"] .page-heading{margin-bottom:16px}\n[data-route=\"gift-speaker\"] .gift-single-speaker{text-align:center;margin:0 0 24px}\n[data-route=\"gift-speaker\"] .gift-single-speaker .speaker-art{width:min(100%,210px);margin:0 auto 12px}\n[data-route=\"gift-speaker\"] .gift-single-speaker h2{font-size:22px;line-height:30px;margin:0}\n[data-route=\"gift-speaker\"] .speaker-price{font-family:var(--qs-ui);font-size:17px;line-height:24px;color:#4F6557;margin:6px 0 0}\n[data-route=\"gift-speaker\"] .gift-engraving .field{margin-bottom:0}\n[data-route=\"gift-speaker\"] .sticky-actions{gap:4px;padding-top:12px;padding-bottom:8px}\n[data-route=\"gift-speaker\"] .sticky-actions .text-button{text-decoration:none}\n@media(max-height:650px){[data-route=\"gift-speaker\"] .topbar{margin-bottom:8px}[data-route=\"gift-speaker\"] .gift-single-speaker .speaker-art{width:160px}[data-route=\"gift-speaker\"] .gift-single-speaker{margin-bottom:16px}}\n";
editorHierarchyStyle.textContent+="\n/* Sound Bazaar: compact filters, album selection, preview and gift review. */\n[data-route=\"bazaar\"] .topbar,[data-route=\"wishlist\"] .topbar{margin-bottom:12px}\n[data-route=\"bazaar\"] .page-heading,[data-route=\"wishlist\"] .page-heading{margin-bottom:20px}\n[data-route=\"bazaar\"] .search-field,[data-route=\"wishlist\"] .search-field{padding:8px 12px;margin:0;background:#FBF6ED;border:1px solid #D9CDBB;border-radius:10px;min-height:48px}\n[data-route=\"bazaar\"] .search-field input,[data-route=\"wishlist\"] .search-field input{font-size:15px;line-height:22px;min-height:30px}\n.bazaar-filter-strip{display:flex;align-items:center;gap:8px;margin:12px 0 20px}\n.bazaar-favorites-filter{display:grid;place-items:center;flex:0 0 44px;width:44px;height:44px;padding:10px;border:0;border-radius:50%;background:transparent;color:#68675B}\n.bazaar-favorites-filter svg{width:20px;height:20px}\n.bazaar-favorites-filter.active{color:#4F6557;background:#E0E2CF}\n.bazaar-favorites-filter.active svg{fill:#4F6557}\n.bazaar-category-scroll{display:flex;align-items:center;gap:4px;min-width:0;overflow:auto;scrollbar-width:none}\n.bazaar-category-scroll>button{flex-shrink:0;min-height:44px;border:0;border-radius:0;padding:10px 12px;background:transparent;font:400 13px/20px var(--qs-ui);color:#68675B;white-space:nowrap}\n.bazaar-category-scroll>button.active{color:#4F6557;font-weight:600;box-shadow:inset 0 -2px #4F6557}\n.album-picker-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 16px}\n.album-picker-card{min-width:0;background:transparent;border:0;box-shadow:none}\n.album-cover-wrap{position:relative;aspect-ratio:1}\n.album-cover-button{display:block;width:100%;height:100%;padding:0;border:0;border-radius:12px;overflow:hidden;background:#E7E4D5;position:relative}\n.album-cover-button>.art{width:100%;height:100%;margin:0;border:0;border-radius:0}\n.album-preview-icon{position:absolute;bottom:10px;left:10px;display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#FBF6EDE6;color:#4F6557}\n.album-preview-icon svg{width:15px;height:15px}\n.album-select-check{position:absolute;top:2px;right:2px;width:44px;height:44px;display:grid;place-items:center;border:0;padding:0;background:transparent}\n.album-select-check>span{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;border:1px solid #7C8977;background:#FBF6EDF2;color:#FBF6ED}\n.album-select-check[aria-pressed=\"true\"]>span{background:#4F6557;border-color:#4F6557}\n.album-select-check svg{width:16px;height:16px;stroke-width:2}\n.album-picker-card[data-selected=\"true\"] .album-cover-button{outline:2px solid #4F6557;outline-offset:3px}\n.album-tile-copy{padding-top:10px}\n.album-tile-copy h2{font-family:var(--qs-ui);font-size:17px;line-height:23px;font-weight:500;letter-spacing:0;margin:0;overflow-wrap:anywhere}\n.album-tile-meta{display:flex;align-items:center;justify-content:space-between;gap:6px;font-size:13px;line-height:18px;color:#68675B;margin-top:2px}\n.album-heart{display:grid;place-items:center;width:36px;height:36px;flex-shrink:0;border:0;padding:8px;background:transparent;color:#4F6557}\n.album-heart svg{width:18px;height:18px}\n.album-heart[aria-pressed=\"true\"] svg{fill:currentColor}\n.album-selection-tray{border:1px solid #D9CDBB;border-radius:10px;background:#FBF6ED;overflow:hidden}\n.album-tray-toggle{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:44px;padding:10px 12px;border:0;background:transparent;font:400 13px/20px var(--qs-ui);color:#4F6557;text-align:left}\n.album-tray-toggle svg{width:16px;height:16px}\n.album-tray-list{list-style:none;padding:0 8px 4px 12px;margin:0;max-height:min(230px,35dvh);overflow:auto}\n.album-tray-list li{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:44px;border-top:1px solid #D9CDBB;font:400 13px/20px var(--qs-ui)}\n.album-tray-list .icon-button{width:44px;height:44px}\n.album-tray-list .icon-button svg{width:16px;height:16px}\n[data-route=\"bazaar\"] .sticky-actions,[data-route=\"wishlist\"] .sticky-actions{padding:10px 24px 12px;gap:8px}\n.album-picker-context{display:flex;flex-direction:column;gap:4px;margin-bottom:24px}\n.album-picker-context>span{font-size:17px;font-weight:500;color:#4F6557}\n.album-picker-context>small{font-size:13px;color:#68675B}\n.gift-collection-details{border:1px solid #D9CDBB;border-radius:14px;background:#FBF6ED;margin-bottom:16px;padding:0 16px}\n.gift-collection-details>summary{list-style:none;display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:80px;cursor:pointer;padding:16px 0}\n.gift-collection-details>summary::-webkit-details-marker{display:none}\n.gift-collection-details strong{display:block;font-size:17px;line-height:24px;font-weight:500}\n.gift-collection-details small{display:block;margin-top:4px;font-size:13px;line-height:18px;color:#68675B}\n.gift-collection-details summary>svg{width:18px;height:18px}\n.gift-collection-details[open] summary>svg{transform:rotate(180deg)}\n.gift-collection-details ul{margin:0;padding:0;list-style:none}\n.gift-collection-details li{padding:10px 0;border-top:1px solid #D9CDBB;font-size:15px;line-height:22px}\n.gift-collection-details>.text-button{display:block;margin:6px 0 10px}\ndialog.album-preview-dialog{position:fixed;box-sizing:border-box;width:min(350px,calc(100vw - 32px));max-height:calc(100dvh - 32px);padding:24px;border-radius:18px;overflow:auto}\ndialog.album-preview-dialog>h2{font-family:var(--qs-display);font-size:22px;line-height:28px;margin:0 32px 16px 0;font-weight:400}\ndialog.album-preview-dialog>[data-action=\"close-modal\"]{position:absolute;top:8px;right:8px;width:44px;height:44px;margin:0;color:#68675B}\ndialog.album-preview-dialog>[data-action=\"close-modal\"] svg{width:18px;height:18px}\n.album-modal-art{width:140px;height:140px;margin:0 auto 12px;border-radius:10px;overflow:hidden}\n.album-modal-art .art{height:100%;width:100%}\ndialog.album-preview-dialog .album-preview-byline{font-size:13px;line-height:18px;color:#68675B;margin:0 0 12px;text-align:center}\ndialog.album-preview-dialog .media-player{margin:0;padding:0;border:0;background:transparent;box-shadow:none}\ndialog.album-preview-dialog .player-times{font-size:12px;line-height:18px}\ndialog.album-preview-dialog .player-controls{margin-top:8px;gap:20px}\ndialog.album-preview-dialog .player-controls button{margin-top:0}\ndialog.album-preview-dialog>.text-button{display:block;margin:12px auto 0;font-size:13px}\n[data-route=\"blessing-preview\"] .blessing-preview-content{display:grid;grid-template-rows:44px minmax(0,1fr) auto;gap:16px;min-height:0;padding:8px 24px 20px}\n[data-route=\"blessing-preview\"] .topbar{display:grid;grid-template-columns:44px minmax(0,1fr) 44px;margin:0 -12px;align-items:center}\n.blessing-preview-title{font:500 17px/24px var(--qs-ui);text-align:center}\n.blessing-preview-stage{container-type:size;display:grid;place-items:center;min-height:0}\n.blessing-preview-stage .template-flip{width:min(100%,280px,72cqh);margin:0}\n[data-route=\"blessing-preview\"] .meta{margin:0;font-size:13px}\n@media(max-height:560px){dialog.album-preview-dialog{padding:18px}.album-modal-art{width:100px;height:100px}dialog.album-preview-dialog>h2{font-size:20px;line-height:26px;margin-bottom:10px}dialog.album-preview-dialog>.text-button{margin-top:4px}}\n";
editorHierarchyStyle.textContent+=".album-picker-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.album-picker-heading>span{font-size:17px;font-weight:500;color:#4F6557}.album-create-link{display:inline-flex;align-items:center;justify-content:center;gap:4px;min-height:44px;padding:8px 0 8px 8px;border:0;background:transparent;color:#4F6557;font:400 13px/20px var(--qs-ui);white-space:nowrap}.album-create-link svg{width:14px;height:14px}.album-create-link:focus-visible{outline:2px solid #4F6557;outline-offset:3px}";
