editorHierarchyStyle.textContent += "\n/* Purchased albums and compact confirmation bar */\n.album-owned-badge{position:absolute;top:10px;left:10px;display:inline-flex;align-items:center;gap:4px;padding:4px 8px;border-radius:20px;background:#FBF6EDF2;color:#4F6557;font:400 12px/18px var(--qs-ui);pointer-events:none}\n.album-owned-badge svg{width:14px;height:14px}\n.bazaar-owned-filter{display:flex;align-items:center;justify-content:center;gap:5px;flex-shrink:0;min-height:44px;padding:8px 12px;border:1px solid #D9CDBB;border-radius:24px;background:transparent;color:#68675B;font:400 13px/20px var(--qs-ui)}\n.bazaar-owned-filter svg{width:16px;height:16px}\n.bazaar-owned-filter.active{background:#E0E2CF;border-color:#E0E2CF;color:#4F6557}\n.album-owned-detail{display:flex;align-items:center;justify-content:center;gap:6px;padding:12px;color:#4F6557;font:400 13px/20px var(--qs-ui)}\n.album-owned-detail svg{width:16px;height:16px}\n.album-selection-footer{width:100%;min-width:0}\n.album-selection-bar{display:flex;align-items:center;justify-content:space-between;gap:12px}\n.album-selection-bar .album-tray-toggle{width:auto;flex:1;gap:6px;min-width:0;min-height:48px;padding:8px 0;color:#68675B;font:400 13px/20px var(--qs-ui)}\n.album-selection-bar .album-tray-toggle:disabled{opacity:1}\n.album-selection-bar .primary{flex:0 0 auto;width:auto;min-width:112px;min-height:48px;padding:12px 20px;margin:0;border:0;border-radius:10px;clip-path:none;background:#4F6557;color:#FBF6ED;font:500 15px/22px var(--qs-ui);box-shadow:none}\n.album-selection-bar .primary:disabled{background:#E3E5DA;color:#777B70}\n.album-selection-footer .album-tray-list{padding:0 0 8px;margin:0 0 8px;border-bottom:1px solid #D9CDBB}\n@media(max-width:350px){.album-selection-bar{gap:8px}.album-selection-bar .primary{min-width:96px;padding:12px}.album-selection-bar .album-tray-toggle{font-size:12px}}\n";
editorHierarchyStyle.textContent += ".art.album-art{background-image:url('assets/album-cover-atlas.svg');background-size:200% 100%;background-repeat:no-repeat;background-color:#E4D6BA}\n.album-art-0{background-position:left center}.album-art-1{background-position:right center}\n.album-object{position:relative;width:100%;aspect-ratio:1;display:grid;place-items:center;padding:15%;isolation:isolate;container-type:inline-size;perspective:1000px;overflow:visible}\n.album-object .album-volume{position:relative;width:100%;height:100%;transform:rotate(-4deg) skewY(2deg);transition:transform .3s ease;filter:drop-shadow(8px 12px 9px #363A3224)}\n.album-volume:before{content:'';position:absolute;inset:4% -5% -3% 5%;background:repeating-linear-gradient(0deg,#D8CEBB 0 1px,#F8F0DF 1px 3px);border:1px solid #C1B49B;border-radius:2px;z-index:-1}\n.album-front{position:relative;display:flex;flex-direction:column;overflow:hidden;width:100%;height:100%;background:#F5EDDC;border:1px solid #C5B99F;border-radius:3px 5px 5px 3px}\n.album-object .album-front>.art{flex:1;min-height:0;width:auto;height:auto;aspect-ratio:auto;margin:0;border-radius:0}\n.album-object .album-front>strong{display:block;padding:7% 9%;font:400 clamp(10px,6cqw,23px)/1.2 var(--qs-display);color:#363A32;text-align:left;overflow-wrap:anywhere}\n.album-format-0 .album-front{padding-left:8%}\n.album-format-0 .album-front:before{content:'';position:absolute;inset:0 auto 0 0;width:8%;background:linear-gradient(90deg,#4F6557,#87917C 65%,#65765F);box-shadow:2px 0 3px #363A3230;z-index:2}\n.album-format-0 .album-front>.art{margin:8% 8% 0;flex:1;border:1px solid #D9CDBB}\n.album-format-1 .album-volume{height:80%;width:84%;transform:rotate(-3deg) skewY(4deg);margin-left:-12%}\n.album-format-1 .album-fold{position:absolute;top:2%;bottom:0;width:39%;right:-29%;background:#DED5BD;transform:skewY(-18deg);transform-origin:left center;border:1px solid #BCAF95;z-index:-1;overflow:hidden;box-shadow:4px 4px 0 #C5B99F}\n.album-fold>.art{width:100%;height:100%;opacity:.65}\n.album-format-1 .album-front>strong{position:absolute;left:0;right:0;bottom:0;background:#FBF6EDEB;padding:8%}\n.album-format-1 .album-volume:before{display:none}\n.album-format-2 .album-volume{height:88%;transform:rotate(-4deg) skewY(3deg)}\n.album-format-2 .album-volume:before{inset:8% -7% -9% 7%;background:#87917C;border-color:#6C7D65;border-radius:5px}\n.album-format-2 .album-front{padding:7%;border-radius:5px;background:#E7E4D5;box-shadow:0 3px 0 #B1B59E}\n.album-format-2 .album-front>strong{position:absolute;left:0;right:0;top:39%;padding:6% 5%;text-align:center;background:#FBF6EDF2;box-shadow:0 1px 2px #363A321A}\n.album-object.album-front-view .album-volume{transform:none}\n.album-object-large{max-width:320px;margin:auto}\n.album-template-preview{display:grid;place-items:center;align-self:stretch;min-height:0;width:100%;padding:0;border:0;background:transparent}\n.album-template-preview .album-object{width:min(100%,290px,65cqh);margin:auto}\n.album-template-carousel{container-type:size}\n.album-template-description{margin:6px auto 0;max-width:260px;font:400 13px/20px var(--qs-ui);color:#68675B}\n.album-picker-heading{flex-wrap:wrap;gap:8px 12px}\n.album-picker-heading>span{font:500 15px/22px var(--qs-ui);color:#4F6557}\n.album-create-link{margin-left:auto}\n.album-cover-button:has(.album-object){background:transparent;overflow:visible;border-radius:8px}\n.album-cover-button>.album-object{width:100%;height:100%}\n.album-preview-button{z-index:3}.album-select-check{z-index:3}\n.album-editor-preview{display:block;width:min(220px,65%);margin:0 auto 18px;padding:0;border:0;background:transparent}\n.album-hero>.album-object{max-width:300px}\n.grid-creation>.album-object{width:100%;margin:0}\n.share-preview>.album-object{max-width:300px;margin:auto}\n.album-preview-cover:has(.album-object){background:transparent;overflow:visible}\n@media(prefers-reduced-motion:reduce){.album-volume{transition:none}}\n";
editorHierarchyStyle.textContent += "\n/* Match My Creativity's card grid in the album picker. */\n#app[data-route=\"album-cards\"] .creation-grid.columns-4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px 10px}\n#app[data-route=\"album-cards\"] .grid-cell,#app[data-route=\"album-cards\"] .grid-creation{min-width:0}\n#app[data-route=\"album-cards\"] .grid-creation{padding:0}\n#app[data-route=\"album-cards\"] .grid-creation>.art{width:100%;aspect-ratio:1;border-radius:8px}\n#app[data-route=\"album-cards\"] .grid-creation strong{font:500 12px/17px var(--qs-ui);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}\n#app[data-route=\"album-cards\"] .grid-creation small{font:400 10px/14px var(--qs-ui)}\n#app[data-route=\"album-cards\"] .selection-check{width:22px;height:22px;top:4px;right:4px}\n.album-details-form .album-appearance{display:grid;grid-template-columns:100px minmax(0,1fr);gap:14px;align-items:center;margin:0 0 24px}\n.album-appearance .album-editor-preview{width:100%;margin:0}\n.album-appearance .option-row{min-height:60px;padding:10px 12px;margin-bottom:8px}\n.album-appearance .option-row strong{font:500 15px/21px var(--qs-ui)}\n.album-appearance .option-row small{font:400 13px/18px var(--qs-ui)}\n.album-back-layout{height:100%;padding:10%;display:flex;flex-direction:column;gap:5%;color:#4F6557;text-align:left;overflow:hidden}\n.album-back-eyebrow{font:500 3.4cqw/1.3 var(--qs-ui);letter-spacing:.12em}\n.album-back-layout h3{font:400 6.3cqw/1.15 var(--qs-display);margin:0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.album-back-layout p{font:400 3.8cqw/1.5 var(--qs-ui);margin:0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}\n.album-back-layout ol{margin:0;padding-left:1.3em;font:400 3.6cqw/1.6 var(--qs-ui)}\n.album-back-layout li{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.album-back-layout small{font:400 3.4cqw/1.3 var(--qs-ui);margin-top:auto}\n.album-back-mark svg{width:7cqw;height:7cqw;stroke-width:1.2}\n.album-back-view.album-format-0 .album-front{padding:0 8% 0 0}\n.album-back-view.album-format-0 .album-front:before{left:auto;right:0}\n.album-back-layout-0 ol{border-top:1px solid #D9CDBB;padding-top:5%}\n.album-back-view.album-format-1 .album-front{background:#E4E5D5}\n.album-back-layout-1{padding:8%;gap:4%;background:linear-gradient(90deg,transparent 48%,#C4C8B6 49%,#EEF0E2 50%,transparent 51%)}\n.album-back-layout-1 p{max-width:85%}\n.album-back-layout-1 .album-back-mark{position:absolute;right:8%;bottom:7%}\n.album-back-view.album-format-2 .album-front{background:#667B69;padding:7%}\n.album-back-layout-2{background:#FBF6ED;padding:9%;text-align:center;gap:4%;border:1px solid #C5B99F}\n.album-back-layout-2 ol{list-style:none;padding:0;border-top:1px solid #D9CDBB;padding-top:5%}\n.album-back-layout-2 .album-back-mark{display:none}\n.album-template-preview .album-back-view{animation:album-back-reveal .24s ease-out}\n@keyframes album-back-reveal{from{opacity:.4;transform:rotateY(-12deg)}to{opacity:1;transform:rotateY(0)}}\n@media(prefers-reduced-motion:reduce){.album-template-preview .album-back-view{animation:none}}\n";
editorHierarchyStyle.textContent += ".album-details-hero{display:block;width:min(100%,250px);padding:0;margin:0 auto 20px;border:0;background:transparent}.album-details-choices{margin:0 0 28px}.album-details-choices .option-row:last-child{margin-bottom:0}";
editorHierarchyStyle.textContent += "\n#app[data-route=\"detail\"] .card-experience{display:grid;grid-template-rows:44px minmax(250px,1fr) 18px auto;gap:10px;min-height:0;padding:4px 24px 10px;overflow:auto}\n#app[data-route=\"detail\"] .card-experience>.topbar{margin:0 -10px;height:44px;display:grid;grid-template-columns:44px minmax(0,1fr) 44px}\n.card-experience-title{font:500 15px/21px var(--qs-ui);color:#68675B;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.card-experience-stage{display:grid;place-items:center;min-height:250px;container-type:size}\n#app[data-route=\"detail\"] .detail-card{width:min(100%,340px,75cqh);padding:0;margin:0;border:0;background:none;display:block}\n#app[data-route=\"detail\"] .detail-card .paper-card{width:100%;max-width:none;margin:0}\n#app[data-route=\"detail\"] .card-flip-hint{margin:0;font:400 12px/18px var(--qs-ui);color:#68675B}\n#app[data-route=\"detail\"] .media-player{width:100%;max-width:340px;justify-self:center;border:0;border-radius:0;background:none;padding:0;margin:0}\n#app[data-route=\"detail\"] .player-times{font:400 11px/16px var(--qs-ui);margin:0}\n#app[data-route=\"detail\"] .player-controls{gap:24px;margin:6px 0 0}\n#app[data-route=\"detail\"] .player-controls .play-button{width:44px;height:44px;min-height:44px}\n#app[data-route=\"detail\"] .player-controls .play-button svg{width:19px;height:19px}\n#app[data-route=\"detail\"] .player-controls .icon-button{width:44px;height:44px}\n#app[data-route=\"detail\"] .player-controls .icon-button svg{width:20px;height:20px}\n#app[data-route=\"detail\"] .sticky-actions{padding:8px 24px 12px;gap:6px}\n#app[data-route=\"detail\"] .sticky-actions>.primary{min-height:44px;padding:10px 16px;font:500 15px/22px var(--qs-ui)}\n#app[data-route=\"detail\"] .detail-toolbar{margin:0;padding:0;border-bottom:0;gap:8px}\n#app[data-route=\"detail\"] .detail-toolbar button{font:400 12px/18px var(--qs-ui);min-height:44px;gap:6px;padding:8px 4px}\n#app[data-route=\"detail\"] .detail-toolbar svg{width:18px;height:18px}\n#app[data-route=\"detail\"] .detail-card .card-back p{max-height:220px;overflow:auto}\n@media(max-height:650px){#app[data-route=\"detail\"] .card-experience{grid-template-rows:44px minmax(210px,1fr) 18px auto;gap:6px}.card-experience-stage{min-height:210px}}\n";
